-- Order notifications: a trigger calls the notify-order edge function on every new order and status change.
-- Secrets live in Supabase Vault and never leave the server:
--   notify_secret   shared secret the edge function checks (generated here)
--   vapid_public / vapid_private   web push keys (generated by the edge function on first run)
create extension if not exists pg_net with schema extensions;

do $$ begin
  if not exists (select 1 from vault.secrets where name = 'notify_secret') then
    perform vault.create_secret(encode(extensions.gen_random_bytes(32), 'hex'), 'notify_secret', 'Shared secret: order trigger -> notify-order');
  end if;
end $$;

-- service-role only: read and write app secrets (used by the edge function)
create or replace function public.app_secret(p_name text)
returns text language sql security definer set search_path to 'public', 'vault'
as $$ select decrypted_secret from vault.decrypted_secrets where name = p_name limit 1 $$;
revoke all on function public.app_secret(text) from public, anon, authenticated;
grant execute on function public.app_secret(text) to service_role;

create or replace function public.set_app_secret(p_name text, p_value text)
returns void language plpgsql security definer set search_path to 'public', 'vault'
as $$
begin
  if p_name not in ('vapid_public', 'vapid_private') then raise exception 'NOT_ALLOWED'; end if;
  if exists (select 1 from vault.secrets where name = p_name) then
    perform vault.update_secret((select id from vault.secrets where name = p_name), p_value);
  else
    perform vault.create_secret(p_value, p_name);
  end if;
end $$;
revoke all on function public.set_app_secret(text, text) from public, anon, authenticated;
grant execute on function public.set_app_secret(text, text) to service_role;

-- anyone: the public push key (it is public by design)
create or replace function public.push_public_key()
returns text language sql stable security definer set search_path to 'public', 'vault'
as $$ select decrypted_secret from vault.decrypted_secrets where name = 'vapid_public' limit 1 $$;
grant execute on function public.push_public_key() to anon, authenticated;

-- trigger
create or replace function public.notify_order_change()
returns trigger language plpgsql security definer set search_path to 'public', 'vault', 'extensions'
as $$
declare v_secret text;
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then return new; end if;
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'notify_secret';
  perform net.http_post(
    url := 'https://hgnfqpxkvnbieqrbynzf.supabase.co/functions/v1/notify-order',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-notify-secret', v_secret),
    body := jsonb_build_object('order_id', new.id, 'event', case when tg_op = 'INSERT' then 'insert' else 'status' end),
    timeout_milliseconds := 5000
  );
  return new;
exception when others then
  return new; -- a notification problem must never block an order
end $$;

drop trigger if exists orders_notify on public.orders;
create trigger orders_notify after insert or update of status on public.orders
for each row execute function public.notify_order_change();
